import json
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from pathlib import Path
S=json.loads(Path('/app/output/spec.json').read_text())
LIMITS=np.array(S['action_types']['joint_position']['panda_joint_limits_rad'])
ORIGINS=[([0,0,.333],[0,0,0]),([0,0,0],[-np.pi/2,0,0]),([0,-.316,0],[np.pi/2,0,0]),([.0825,0,0],[np.pi/2,0,0]),([-.0825,.384,0],[-np.pi/2,0,0]),([0,0,0],[np.pi/2,0,0]),([.088,0,0],[np.pi/2,0,0])]
def tf(p,r):
 t=np.eye(4);t[:3,:3]=Rotation.from_euler('xyz',r).as_matrix();t[:3,3]=p;return t
def fk(q):
 t=tf([0,-.4,.6],[0,0,np.pi/2])
 for qi,(p,r) in zip(q,ORIGINS):t=t@tf(p,r)@tf([0,0,0],[0,0,qi])
 return t@tf([0,0,.107],[0,0,-np.pi/4])
def ik(p,R,q):
 def err(a):
  t=fk(a)
  return np.r_[5*(t[:3,3]-p),Rotation.from_matrix(R@t[:3,:3].T).as_rotvec(),.015*(a-q)]
 sol=least_squares(err,q,bounds=(LIMITS[:,0]+.0001,LIMITS[:,1]-.0001),max_nfev=500,ftol=1e-11,xtol=1e-11,gtol=1e-11)
 return sol.x, np.linalg.norm(fk(sol.x)[:3,3]-p),np.linalg.norm(err(sol.x)[3:6])
def unproject(cam,u,v,d):
 c=S['cameras'][cam]; k=np.array(c['intrinsic_cv']); t=np.array(c['cam2world_gl'])
 return t[:3,3]+t[:3,:3]@np.array([(u-k[0,2])*d/k[0,0],-(v-k[1,2])*d/k[1,1],-d])
def plane_point(cam,u,v,z):
 a=unproject(cam,u,v,1);o=np.array(S['cameras'][cam]['cam2world_gl'])[:3,3]
 return o+(a-o)*(z-o[2])/(a[2]-o[2])
if __name__=='__main__':
 m=json.loads(Path('/app/output/initial/meta.json').read_text());q=np.array(m['proprio']['now'][:7]);print('FK',fk(q));print('observed',m['proprio']['now'][16:23])
 for cam,pix in [('forward',[(188,249),(159,249),(130,248),(110,246),(81,247)]),('right',[(182,247),(205,255),(230,267),(247,275),(278,286)]),('left',[(90,265),(116,255),(139,248),(154,242),(173,235)])]:
  d=np.load('/app/output/initial/depth_'+cam+'.npy')[-1]
  for u,v in pix:print(cam,u,v,float(d[v,u]),unproject(cam,u,v,float(d[v,u])))
